import React, { useState, useEffect, useCallback } from 'react';
import ReactGA from 'react-ga4';
import { ref, onValue, push, query, orderByChild, limitToLast, get, set } from 'firebase/database';
import { database } from '../../firebase';
import { getRandomQuestion } from '../../services/dataService';
import Leaderboard from './Leaderboard';
import './GameMode.css';


const GameMode = () => {
  const [mode, setMode] = useState('practice');
  const [question, setQuestion] = useState(null);
  const [score, setScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState(60);
  const [gameActive, setGameActive] = useState(false);
  const [stats, setStats] = useState({ correct: 0, total: 0 });
  const [playerName, setPlayerName] = useState('');
  const [showNameInput, setShowNameInput] = useState(false);
  // const [leaderboard, setLeaderboard] = useState([]);
  // const [questionStats, setQuestionStats] = useState({});
  const [isAdmin, setIsAdmin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');
  // 修改 leaderboard 的初始化，移除 localStorage 相关代码
  const [leaderboard, setLeaderboard] = useState([]);
    // 修改 questionStats 的初始化
  const [questionStats, setQuestionStats] = useState({});

//  const [questionStats, setQuestionStats] = useState(() => {
//    // 从本地存储加载统计数据
//    const savedStats = localStorage.getItem('questionStats');
//    return savedStats ? JSON.parse(savedStats) : {};
//  });

  // 修改排行榜 useEffect，添加排序功能
  useEffect(() => {
    const leaderboardRef = ref(database, 'leaderboard');
    const topScoresQuery = query(leaderboardRef, orderByChild('score'), limitToLast(10));

    onValue(topScoresQuery, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const scores = Object.values(data)
          .sort((a, b) => b.score - a.score)
          .slice(0, 10);
        setLeaderboard(scores);
      }
    });
  }, []);

//  // 添加 useEffect 来从 Firebase 加载统计数据
//  useEffect(() => {
//    const statsRef = ref(database, 'questionStats');
//    onValue(statsRef, (snapshot) => {
//      const data = snapshot.val();
//      if (data) {
//        setQuestionStats(data);
//      }
//    });
//  }, []);

// 修改排行榜 useEffect，添加排序功能
useEffect(() => {
  const leaderboardRef = ref(database, 'leaderboard');
  const topScoresQuery = query(leaderboardRef, orderByChild('score'), limitToLast(10));

  onValue(topScoresQuery, (snapshot) => {
    const data = snapshot.val();
    if (data) {
      const scores = Object.values(data)
        .sort((a, b) => b.score - a.score)
        .slice(0, 10);
      setLeaderboard(scores);
    }
  });
}, []);


//  // 修改 leaderboard 的初始化
//  const [leaderboard, setLeaderboard] = useState(() => {
//    const savedScores = localStorage.getItem('leaderboard');
//    return savedScores ? JSON.parse(savedScores) : [];
//  });

  const getNewQuestion = () => {
    const newQuestion = getRandomQuestion();
    setQuestion(newQuestion);
  };

//  // 添加重置统计数据的功能
//  const resetStats = () => {
//    if (window.confirm('确定要清零所有统计数据吗？')) {
//      setQuestionStats({});
//      localStorage.removeItem('questionStats');
//    }
//  };

// 修改 resetStats 函数
  const resetStats = () => {
    if (window.confirm('确定要清零所有统计数据吗？')) {
      const statsRef = ref(database, 'questionStats');
      set(statsRef, {});
    }
  };

  const handleAnswer = (selectedEffect) => {
  if (!question) return;
  const isCorrect = selectedEffect === question.correctAnswer;

    // 发送答题事件到 GA
    ReactGA.event({
        category: mode,
        action: isCorrect ? 'correct_answer' : 'wrong_answer',
        label: question.questionType === 'policy'
            ? `${question.policy}-${question.variable}`
            : `${question.event}-${question.curve}`,
        value: isCorrect ? 1 : 0  // 添加数值统计
    });

//    // 移除 isAdmin 检查，让所有模式下的答题都被统计
//    setQuestionStats(prev => {
//        const questionKey = question.questionType === 'policy'
//          ? `${question.policy}-${question.variable}`
//          : `${question.event}-${question.curve}`;
//
//        const currentStats = prev[questionKey] || { correct: 0, total: 0 };
//        const newStats = {
//          ...prev,
//          [questionKey]: {
//            correct: currentStats.correct + (isCorrect ? 1 : 0),
//            total: currentStats.total + 1,
//            errorRate: ((currentStats.total + 1 - (currentStats.correct + (isCorrect ? 1 : 0))) / (currentStats.total + 1) * 100).toFixed(1)
//          }
//        };
//
//        localStorage.setItem('questionStats', JSON.stringify(newStats));
//        return newStats;
//    });
//
//    if (mode === 'competition') {
//      setScore(prev => prev + (isCorrect ? 10 : -10));
//    }
    // 更新 Firebase 中的统计数据 // 修改键名处理，替换特殊字符
    const questionKey = question.questionType === 'policy'
    ? `${question.policy}_${question.variable}`.replace(/[.#$/[\]]/g, '_').replace(/\//g, '_')
    : `${question.event}_${question.curve}`.replace(/[.#$/[\]]/g, '_').replace(/\//g, '_');

  const statsRef = ref(database, 'questionStats');
  get(statsRef)
    .then((snapshot) => {
      const currentStats = snapshot.val() || {};
      const questionStats = currentStats[questionKey] || { correct: 0, total: 0 };

      const newStats = {
        ...currentStats,
        [questionKey]: {
          correct: questionStats.correct + (isCorrect ? 1 : 0),
          total: questionStats.total + 1,
          errorRate: ((questionStats.total + 1 - (questionStats.correct + (isCorrect ? 1 : 0))) / (questionStats.total + 1) * 100).toFixed(1)
        }
      };

      return set(statsRef, newStats);
    })
    .catch((error) => {
      console.error("Error updating stats:", error);
    });

  if (mode === 'competition') {
    setScore(prev => prev + (isCorrect ? 10 : -10));
  }

    setStats(prev => ({
      correct: prev.correct + (isCorrect ? 1 : 0),
      total: prev.total + 1
    }));

    alert(isCorrect ?
      `Correct!\n${question.explanation}` :
      `Wrong. The correct answer is ${question.correctAnswer}\n${question.explanation}`
    );

    getNewQuestion();
  };

  const handleStartCompetition = () => {
    setMode('competition');
    setShowNameInput(true);
  };

  const handleNameSubmit = (e) => {
    e.preventDefault();
    setShowNameInput(false);
    startGame();
  };

  const startGame = () => {
    setGameActive(true);
    setScore(0);
    setStats({ correct: 0, total: 0 });
    if (mode === 'competition') {
      setTimeLeft(60);
    }
    getNewQuestion();
  };


  // 使用 useCallback 包装 handleGameOver
  const handleGameOver = useCallback(() => {
    const finalScore = score;
    const accuracy = Math.round(stats.correct/stats.total*100);

    const newScore = {
     playerName: playerName || 'Anonymous',
     score: finalScore,
     accuracy: accuracy,
     timestamp: new Date().toISOString()
    };

    // 保存到 Firebase
    const leaderboardRef = ref(database, 'leaderboard');
  push(leaderboardRef, newScore)
    .then(() => {
      // 发送到 GA
      ReactGA.event({
        category: 'competition',
        action: 'game_over',
        label: playerName || 'Anonymous',
        value: finalScore
      });

      alert(`Game Over!\nFinal Score: ${finalScore}\nAccuracy: ${accuracy}%`);
    })
    .catch((error) => {
      console.error("Error updating leaderboard:", error);
      alert(`Game Over!\nFinal Score: ${finalScore}\nAccuracy: ${accuracy}%`);
    });
}, [score, stats.correct, stats.total, playerName]);


//    // 移到这里，在 newScore 定义之后
//    setLeaderboard(prev => {
//      const newLeaderboard = [...prev, newScore]
//        .sort((a, b) => b.score - a.score)
//        .slice(0, 10);
//      localStorage.setItem('leaderboard', JSON.stringify(newLeaderboard));
//      return newLeaderboard;
//    });
//
//    alert(`Game Over!\nFinal Score: ${finalScore}\nAccuracy: ${accuracy}%`);
//  }, [score, stats.correct, stats.total, playerName]); // 添加依赖项


  // 计时器 useEffect
  useEffect(() => {
    let timer;
    if (mode === 'competition' && gameActive && timeLeft > 0) {
      timer = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            setGameActive(false);
            clearInterval(timer);
            handleGameOver();
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [mode, gameActive, timeLeft, handleGameOver]);

  // 排行榜 useEffect
  useEffect(() => {
    const leaderboardRef = ref(database, 'leaderboard');
    onValue(leaderboardRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const scores = Object.values(data)
          .sort((a, b) => b.score - a.score)
          .slice(0, 10);
        setLeaderboard(scores);
      }
    });
  }, []);



// renderStats 函数保持不变
  const renderStats = () => {
    const sortedStats = Object.entries(questionStats)
      .sort((a, b) => parseFloat(b[1].errorRate) - parseFloat(a[1].errorRate));


    return (
      <div className="question-stats">
        <h3>错误率统计</h3>
        <button onClick={resetStats} className="reset-stats-button">
          清零统计数据
        </button>
        <div className="stats-list">
          {sortedStats.length > 0 ? (
            sortedStats.map(([question, stats]) => (
              <div key={question} className="stat-item">
                <div className="question-text">{question}</div>
                <div className="error-rate">错误率: {stats.errorRate}%</div>
                <div className="attempt-count">尝试次数: {stats.total}</div>
              </div>
            ))
          ) : (
            <div className="no-stats">暂无统计数据</div>
          )}
        </div>
      </div>
    );
  };

  const handleAdminLogin = (e) => {
    e.preventDefault();
    if (adminPassword === 'admin') {
        setIsAdmin(true);
    } else {
      alert('密码错误');
    }
  };



  return (
    <div className="game-container">
      <div className="mode-selector">
        <button
          onClick={() => setMode('practice')}
          className={mode === 'practice' ? 'active' : ''}
        >
          Practice Mode
        </button>
        <button
          onClick={handleStartCompetition}
          className={mode === 'competition' ? 'active' : ''}
        >
          Competition Mode
        </button>
      </div>

      {showNameInput ? (
        <div className="name-input-container">
          <form onSubmit={handleNameSubmit}>
            <input
              type="text"
              value={playerName}
              onChange={(e) => setPlayerName(e.target.value)}
              placeholder="Enter your name (optional)"
            />
            <button type="submit">Start Game</button>
          </form>
        </div>
      ) : !gameActive ? (
        mode === 'practice' && <button onClick={startGame} className="start-button">
          Start Game
        </button>
      ) : (
        <div className="game-area">
          {mode === 'competition' && (
            <div className="game-stats">
              <div>Time: {timeLeft}s</div>
              <div>Score: {score}</div>
            </div>
          )}

          {question && (
            <div className="question-area">
              <h3>Question:</h3>
              {question.questionType === 'policy' ? (
                <div className="question-content">
                  <div className="question-policy">
                    <strong>Policy:</strong><br />
                    {question.policy}
                  </div>
                  <div className="question-target">
                    <strong>Effect on:</strong><br />
                    {question.variable}
                  </div>
                </div>
              ) : (
                <div className="question-content">
                  <div className="question-event">
                    <strong>Event:</strong><br />
                    {question.event}
                  </div>
                  <div className="question-target">
                    <strong>Effect on:</strong><br />
                    {question.curve} in {question.diagram}
                  </div>
                </div>
              )}

              <div className="answer-buttons">
                <button onClick={() => handleAnswer('increase')}>
                  Increase
                </button>
                <button onClick={() => handleAnswer('decrease')}>
                  Decrease
                </button>
              </div>
            </div>
          )}

          <div className="stats">
            Accuracy: {stats.total > 0 ? Math.round(stats.correct/stats.total*100) : 0}%
            ({stats.correct}/{stats.total})
          </div>
        </div>
      )}

      {/* 排行榜对所有人可见 */}
      {mode === 'competition' && !gameActive && (
          <div className="leaderboard-section">
            <h3>Top 10 Scores</h3>
            <Leaderboard scores={leaderboard} />
          </div>
      )}

      {/* 统计数据只对管理员可见 */}
      {!gameActive && (
          <div className="admin-section">
            {!isAdmin ? (
              <form onSubmit={handleAdminLogin} className="admin-login">
                <input
                  type="password"
                  value={adminPassword}
                  onChange={(e) => setAdminPassword(e.target.value)}
                  placeholder="管理员密码"
                />
                <button type="submit">查看统计</button>
              </form>
            ) : (
              <div>
                {renderStats()}
                <button onClick={() => setIsAdmin(false)}>退出管理员模式</button>
              </div>
            )}
          </div>
      )}
    </div>
  );
};

export default GameMode;